sys_script_include.script:
var FreshGuard360DashboardData = Class.create();
FreshGuard360DashboardData.prototype = Object.extendsObject(AbstractAjaxProcessor, {
    getDashboardMetrics: function() {
        var result = { kpis: {}, tables: {} };
        result.kpis.totalStores = this._getCount("x_fresh_guard_360_store", "");
        result.kpis.checklistsCompleted = this._getCount("x_fresh_guard_360_daily_checklist", "");
        result.kpis.openIssues = this._getCount("x_fresh_guard_360_issue", "");
        result.kpis.highRisks = this._getCount("x_fresh_guard_360_issue", "risk_level=high^ORrisk_level=critical^ORpriority=1^ORpriority=2");
        result.kpis.overdueCapa = this._getCount("x_fresh_guard_360_capa", "status!=completed^status!=closed");
        result.kpis.openMaintenance = this._getCount("x_fresh_guard_360_maintenance_ticket", "state!=3^state!=4");
        return JSON.stringify(result);
    },
    _getCount: function(tableName, query) {
        try {
            var ga = new GlideAggregate(tableName);
            if (query) ga.addEncodedQuery(query);
            ga.addAggregate("COUNT");
            ga.query();
            return ga.next() ? parseInt(ga.getAggregate("COUNT"), 10) : 0;
        } catch (e) { return 0; }
    },
    type: "FreshGuard360DashboardData"
});
